 host=root.querySelector('.forest-game');chapter=Number(learning.rpgLastChapter)||0;host.dataset.chapter=chapter;const cover=q('.realm-cover');cover.querySelector('h1').textContent='字靈森境 · 學習村';cover.querySelector('p').textContent='大地圖連接森林三章同六座學習建築。行到門口就可以入屋練寫字、讀音、默書、認字同互動遊戲。';cover.querySelector('.cover-actions').insertAdjacentHTML('beforebegin',`<div class="chapter-select" role="group" aria-label="選擇故事章節">${chapters.map((c,i)=>`<button data-chapter="${i}"><span>${c.icon}</span><b>${c.badge}</b><small>${c.name}</small></button>`).join('')}</div>`);document.body.classList.add('game-active');canvas=q('#forestCanvas');ctx=canvas.getContext('2d',{alpha:false});selectChapter(chapter);bind();resize();draw(0);running=true;last=performance.now();raf=requestAnimationFrame(loop);if(learning.rpgAutoResume&&learning.rpgWorldState){q('#gameCover').classList.add('hidden-game');restoreWorldState();learning.rpgAutoResume=false;saveLearning();initAudio();say('返到學習村門口，繼續探索啦！');canvas.focus()}
