function unmount(){running=false;cancelAnimationFrame(raf);resizeObs?.disconnect();listeners.splice(0).forEach(off=>off());document.body.classList.remove('game-active');window.ZiziVoice?.stop?.();window.speechSynthesis?.cancel?.();Object.keys(keys).forEach(k=>keys[k]=false);resetJoystick();host=null;canvas=null;ctx=null}
