function finishSideChest(obj,challenge,assisted=false){obj.done=true;learning.inventory=learning.inventory||{};const loot=['蜜糖餅','月石','彩虹羽'][chapter];learning.inventory[loot]=(learning.inventory[loot]||0)+1;learning.rpgSideChests=(learning.rpgSideChests||0)+1;saveLearning();const bonus=(assisted?3:8)+(learning.upgrades?.charm||0)*3;window.ZiziProgress?.award(assisted?'用提示解開寶箱':'完成不同寶箱挑戰',assisted?6:16,bonus,assisted?0:1);q('#rpgModal').classList.add('hidden-game');mode='explore';burst('💰');say(`完成「${challenge.prompt}」！得到${loot}同 ${bonus} 個金幣。`)}
function showTraveller(obj){mode='side';resetJoystick();const fruit=['蘋果','桃子','星果'][chapter],have=learning.inventory?.[fruit]||0;q('#rpgModal').innerHTML=`<div class="battle-card side-card" role="dialog" aria-modal="true"><span class="side-icon">🧙</span><span class="battle-tag">地圖支線 · 森林旅人</span><h2>${have?`你搵到${fruit}！`:`可以幫我搵${fruit}嗎？`}</h2><p>${have?'旅人會用稀有嘅探險徽章交換。':'果實藏喺小路附近，行近閃光果樹再按「採集」。'}</p><div class="cover-actions"><button class="game-primary traveller-action">${have?'交出果實':'接受任務'}</button><button class="game-secondary traveller-close">遲啲再嚟</button></div></div>`;q('#rpgModal').classList.remove('hidden-game');q('.traveller-close').onclick=()=>{q('#rpgModal').classList.add('hidden-game');mode='explore'};q('.traveller-action').onclick=()=>{if(have){learning.inventory[fruit]--;learning.inventory['旅人徽章']=(learning.inventory['旅人徽章']||0)+1;obj.done=true;saveLearning();window.ZiziProgress?.award('完成旅人委託',24,12,1);burst('🏅');say('旅人送你一枚徽章，營地收藏袋會見到！')}else say(`支線已記低：尋找一個${fruit}。`);q('#rpgModal').classList.add('hidden-game');mode='explore'}}
