function useSpark(){if(mode!=='explore')return;const now=performance.now(),cooldown=Math.max(2600,5200-(learning.upgrades?.lens||0)*700);if(now<sparkReadyAt){say('字光充能中，再等一陣。');return}sparkUntil=now+3000;sparkReadyAt=now+cooldown;tone(760,.18);const hidden=sideObjects.filter(x=>!x.done).sort((a,b)=>distance(player.x,player.y,a.x,a.y)-distance(player.x,player.y,b.x,b.y))[0],main=nearestObjective(),target=hidden&&distance(player.x,player.y,hidden.x,hidden.y)<430?{x:hidden.x,y:hidden.y,side:hidden}:main,t=target?.side?`字光感應到附近有${target.side.name}！跟住光線探索。`:target?.item?`字光感應到「${target.item.glyph}」，跟住光線去收集。`:phase===1?'字光指住左上方符文台。':phase===3?'字光指住右上方神殿。':phase===5?'字光指住北面古門。':'字光指住伙伴藏身處。';sparkTarget=target;say(t);speak(t,'character');const btn=q('#sparkBtn');btn.classList.add('charging');setTimeout(()=>btn?.classList.remove('charging'),cooldown)}function distance(a,b,c,d){return Math.hypot(a-c,b-d)}
function nearestObjective(){const remaining=questItems.filter(i=>!i.found);if(phase%2===0&&remaining.length){const item=[...remaining].sort((a,b)=>distance(player.x,player.y,a.x,a.y)-distance(player.x,player.y,b.x,b.y))[0];return{x:item.x,y:item.y,item}}const points=[[260,430],[300,180],[1350,685],[1450,145],[1210,385],[835,105]],p=points[Math.min(phase,5)];return{x:p[0],y:p[1]}}
function startEncounter(){mode='battle';Object.keys(keys).forEach(k=>keys[k]=false);resetJoystick();const spirit=chapters[chapter].spirits[Math.floor(phase/2)],questions=chapters[chapter].questions,recent=Array.isArray(learning.recentSpiritQuestions)?learning.recentSpiritQuestions:[],fresh=questions.map((_,i)=>i).filter(i=>!recent.includes(`${chapter}-${i}`)),pool=fresh.length?fresh:questions.map((_,i)=>i);battle={spirit,hp:3,index:pool[Math.floor(Math.random()*pool.length)],used:[],turn:0,locked:false};showBattle('',900);tone(420,.2);speak(`${spirit.name}出現咗。今次有三種唔同挑戰，同佢一齊玩啦。`,'character')}
