function showBattle(message='',voiceDelay=250){const questions=chapters[chapter].questions,b=battle,question=questions[b.index],pos=b.spirit.col*33.333,challenge=['listen','hunt','echo'][b.turn%3],labels={listen:'聽音選詞',hunt:'飛行字靈',echo:'回聲揭牌'},instructions={listen:'聽清楚旁白，揀出正確詞語。',hunt:'目標字靈飛緊，睇準先捕捉！',echo:'逐張揭開回聲牌；聽到想要嘅詞，再按多次確認。'};b.locked=false;q('#rpgModal').innerHTML=`<div class="battle-card battle-${challenge}" role="dialog" aria-modal="true" aria-labelledby="battleTitle"><div class="battle-scene"><div class="spirit-portrait" style="background-position:${pos}% 66.666%" aria-label="${b.spirit.name}"></div><div><span class="battle-tag">${labels[challenge]} · ${b.spirit.title}</span><h2 id="battleTitle">${b.spirit.name}</h2><div class="bond-meter" aria-label="成為伙伴進度"><i style="width:${(3-b.hp)/3*100}%"></i></div><small class="battle-combo">🔥 ${combo} 連擊 · 尚餘 ${b.hp} 關</small></div></div><p class="battle-copy">${message||instructions[challenge]}</p><button class="game-secondary hear-battle">🔊 再聽任務</button><div class="battle-choices ${challenge}">${question.choices.map((c,i)=>`<button data-battle-answer="${c}" style="--battle-i:${i}" class="${challenge==='echo'?'echo-card':''}">${challenge==='echo'?'<span>❔</span><b>回聲牌</b>':c}</button>`).join('')}</div></div>`;q('#rpgModal').classList.remove('hidden-game');q('.hear-battle').onclick=()=>speak(question.say);q('#rpgModal').querySelectorAll('[data-battle-answer]').forEach(btn=>btn.onclick=()=>{if(challenge==='echo'&&!btn.dataset.revealed){btn.dataset.revealed='1';btn.classList.add('revealed');btn.innerHTML=`<span>🔊</span><b>${btn.dataset.battleAnswer}</b>`;speak(btn.dataset.battleAnswer);return}answerBattle(btn.dataset.battleAnswer)});setTimeout(()=>{if(mode==='battle'&&battle&&chapters[chapter].questions[battle.index]===question)speak(question.say)},voiceDelay)}
function answerBattle(value){const questions=chapters[chapter].questions,question=questions[battle.index];if(battle.locked)return;battle.locked=true;q('#rpgModal').querySelectorAll('[data-battle-answer]').forEach(x=>x.disabled=true);battle.used.push(battle.index);rememberSpiritQuestion(battle.index);if(value===question.target){battle.hp--;combo++;syncAdventureHud();tone(720+Math.min(150,combo*18),.14);burst(combo>=5?'🔥':'✨');if(battle.hp<=0){captureSpirit();return}nextBattleQuestion();setTimeout(()=>showBattle(`答啱啦！下一關玩法會轉一轉。${combo>=5?'連擊力量提升！':''}`,420),500)}else{combo=0;syncAdventureHud();tone(230,.13);q('.battle-copy').textContent=`差少少！${question.hint} 下一題會換玩法。`;speak(question.hint);nextBattleQuestion();setTimeout(()=>showBattle('字靈換咗另一條題目，一齊再試！',500),1500)}}
