function draw(){if(!ctx||!canvas)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height;ctx.save();ctx.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);ctx.fillStyle='#91bd78';ctx.fillRect(0,0,w,h);drawVillageGround();if(mapImage.complete&&mapImage.naturalWidth)ctx.drawImage(mapImage,-camera.x,-camera.y,BASE.w,BASE.h);drawVillageOverlay();drawGrass();drawTargets();drawSideObjects();drawQuestItems();drawSparkGuide();drawCompanion();drawTrailEffect();drawPlayer();ctx.restore()}
